{

    internal InnerPaymentCredentialProviderCoinbaseCdpConfigurationInputFactory CoinbaseCdpConfigurationFactory { get; set; }

    internal InnerPaymentCredentialProviderStripePrivyConfigurationInputFactory StripePrivyConfigurationFactory { get; set; }

    protected override Humidifier.BedrockAgentCore.PaymentCredentialProviderTypes.PaymentProviderConfigurationInput Create()
    {
        var paymentProviderConfigurationInputResult = CreatePaymentProviderConfigurationInput();
        factoryAction?.Invoke(paymentProviderConfigurationInputResult);

        return paymentProviderConfigurationInputResult;
    }

    private Humidifier.BedrockAgentCore.PaymentCredentialProviderTypes.PaymentProviderConfigurationInput CreatePaymentProviderConfigurationInput()
    {
        var paymentProviderConfigurationInputResult = new Humidifier.BedrockAgentCore.PaymentCredentialProviderTypes.PaymentProviderConfigurationInput();

        return paymentProviderConfigurationInputResult;
    }
    public override void CreateChildren(Humidifier.BedrockAgentCore.PaymentCredentialProviderTypes.PaymentProviderConfigurationInput result)
    {
        base.CreateChildren(result);

        result.CoinbaseCdpConfiguration ??= CoinbaseCdpConfigurationFactory?.Build();
        result.StripePrivyConfiguration ??= StripePrivyConfigurationFactory?.Build();
    }

} // End Of Class

